# A measure check on thread replies, copied verbatim from the design that set it: of the last 50
# owner thread turns (from the responder's first turn on, at least 20), how many waited over 30 s for
# a first reply. It prints a summary line, then the count. test/responder-e2e.test.mjs runs it with
# sh in its fixture's main checkout.
node docs/devteam/scripts/devteam.mjs thread list --all --json | node -e 'let s="";process.stdin.on("data",d=>s+=d).on("end",()=>{const th=JSON.parse(s);const all=th.flatMap(t=>t.turns);const fr=all.filter(u=>u.writer==="responder").map(u=>Date.parse(u.at)).sort((a,b)=>a-b)[0]??0;const o=[];for(const t of th){const ts=t.turns.map(u=>({by:u.by,at:Date.parse(u.at)}));const res=t.resolved_at?Date.parse(t.resolved_at):null;for(const u of ts.filter(u=>u.by==="owner"&&u.at>=fr)){const r=ts.find(x=>x.by!=="owner"&&x.at>u.at);if(!r&&res&&res>u.at)continue;o.push({at:u.at,d:((r?r.at:Date.now())-u.at)/1000})}}o.sort((a,b)=>a.at-b.at);const w=o.slice(-50);if(!w.length){console.error("no owner turns yet");process.exit(1)}if(fr&&w.length<20){console.error("only "+w.length+" owner turns since the responder started; the measure needs 20");process.exit(1)}const slow=w.filter(x=>x.d>30);console.log("owner turns: "+w.length+(fr?" since the responder started":"")+", over 30 s: "+slow.map(x=>Math.round(x.d)).join(" "));console.log(slow.length)})'
